// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Proxy} from "../src/Proxy.sol";

contract InvMutTest is Test {
    Proxy c;
    function setUp() public { c = new Proxy(); }
    function testFuzz_property(address callee, bytes memory data, uint256 ethToSend) public {
        vm.assume(callee != address(0));
        vm.assume(callee != address(c));
        ethToSend = bound(ethToSend, 0, 1000 ether);
        vm.deal(address(this), ethToSend);
        vm.deal(address(c), ethToSend);
        uint256 balanceBefore = address(c).balance;
        bool ok = false;
        try c.forward(callee, data) { ok = true; } catch { ok = false; }
        if (ok) {
            uint256 balanceAfter = address(c).balance;
            assertTrue(balanceAfter >= balanceBefore);
        }
    }
}
